actions.script:
const current = ec.service.sync().name('ironstone.ContactServices.get#ImportDraft').parameters({importId: importId}).call()
if (!current?.found) { ec.message.addError(ec.l10n.localize('This import is not available; start again from the file')); return }
const parsed = ec.service.sync().name('mantle.party.ContactImportServices.parse#ContactFile').parameters({fileLocation: current.fileLocation,
    fileName: current.draft.fileExt === 'vcf' ? 'source.vcf' : 'source.csv', presetId: current.draft.fileKind === 'csv' ? current.draft.presetId : null,
    sampleSize: 1}).call()
if (ec.message.hasError()) return
const mapping = Object.assign({}, current.draft.columnMapping || {})
const columns = Array.from(parsed.columnList || [])
columns.forEach((column, index) => {
    if (index >= 100) return
    const value = context.get('col_' + index)
    mapping[column.columnName] = value ? String(value) : null
})
if (!Object.values(mapping).some((target) => target)) { ec.message.addError(ec.l10n.localize('Map at least one column')); return }
ec.service.sync().name('ironstone.ContactServices.store#ImportDraft').parameters({importId: importId, fields: {columnMapping: mapping, status: 'mapped'}}).call()

const current = ec.service.sync().name('ironstone.ContactServices.get#ImportDraft').parameters({importId: importId}).call()
if (!current?.found) { ec.message.addError(ec.l10n.localize('This import is not available; start again from the file')); return }
const parsed = ec.service.sync().name('mantle.party.ContactImportServices.parse#ContactFile').parameters({fileLocation: current.fileLocation,
    fileName: current.draft.fileExt === 'vcf' ? 'source.vcf' : 'source.csv', presetId: current.draft.fileKind === 'csv' ? current.draft.presetId : null,
    sampleSize: 1}).call()
if (ec.message.hasError()) return
ec.service.sync().name('ironstone.ContactServices.store#ImportDraft').parameters({importId: importId, fields: {columnMapping: parsed.columnMapping || {}}}).call()
if (!ec.message.hasError()) ec.message.addMessage(ec.l10n.localize('Mapped from the file kind'), 'success')

const L = (text) => ec.l10n.localize(text)
const current = ec.service.sync().name('ironstone.ContactServices.get#ImportDraft').parameters({importId: importId}).call() || {}
hasDraft = !!current.found
mapRows = []
targetOptions = []
if (!hasDraft) return
draft = current.draft
const parsed = ec.service.sync().name('mantle.party.ContactImportServices.parse#ContactFile').parameters({fileLocation: current.fileLocation,
    fileName: draft.fileExt === 'vcf' ? 'source.vcf' : 'source.csv', presetId: draft.fileKind === 'csv' ? draft.presetId : null, sampleSize: 3}).call()
if (ec.message.hasError()) { parseError = ec.message.getErrorsString(); ec.message.clearErrors(); hasDraft = false; return }
const mapping = draft.columnMapping || parsed.columnMapping || {}
const targets = Array.from(parsed.targetFieldList || []).filter((target) => target.fieldName)
const known = new Set(targets.map((target) => target.fieldName))
// a preset's own targets (an Outlook slot with its purpose, phone7:Other) are offered as they are
const describe = (value) => {
    const [field, purpose] = String(value).split(':')
    const base = targets.find((target) => target.fieldName === field)
    return (base ? base.description : field) + (purpose ? ' (' + purpose.replace(/^(Phone|Email|Postal)/, '') + ')' : '')
}
for (const value of Object.values(mapping)) if (value && !known.has(value)) { known.add(value); targets.push({fieldName: value, description: describe(value)}) }
targetOptions = targets
mapRows = Array.from(parsed.columnList || []).slice(0, 100).map((column) => {
    const samples = Array.from(column.sampleValues || []).filter((value) => value != null && String(value).trim()).map((value) => String(value).trim().substring(0, 30))
    return {columnName: column.columnName, targetField: Object.prototype.hasOwnProperty.call(mapping, column.columnName) ? (mapping[column.columnName] || '') : (column.targetField || ''),
        label: column.columnName + (samples.length ? ' · ' + samples.slice(0, 2).join(', ') : '')}
})
columnCount = (parsed.columnList || []).length
mappedCount = mapRows.filter((row) => row.targetField).length
presetLabel = {google: 'Google Contacts CSV', outlook: 'Outlook CSV', generic: 'CSV', vcard: 'vCard'}[parsed.presetId] || parsed.presetId
